import React from 'react';
import ExporterSourcingOffers from '../components/SourcingHubPage';
import WeeklyUpdate from '../components/WeeklyUpdate';
import KnowledgeHubHighlights from '../components/KnowledgeHubHighlights';

const DashboardPage = ({ onNavigate }) => {
    return (
        <div className="w-full">
            <HeroSection />
            <div className="container mx-auto px-4 space-y-8 py-8">
                <MarketPrices />
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <div className="lg:col-span-2">
                        <ExporterSourcingOffers onNavigate={onNavigate} />
                    </div>
                    <div>
                        <WeeklyUpdate onNavigate={onNavigate} />
                    </div>
                </div>
                <KnowledgeHubHighlights onNavigate={onNavigate} />
            </div>
        </div>
    );
};

const HeroSection = () => (
    <div
        className="relative h-80 bg-cover bg-center text-white"
        style={{
            backgroundImage:
                "url('https://images.pexels.com/photos/1400249/pexels-photo-1400249.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1')",
        }}
    >
        <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
            <div className="text-center">
                <h1 className="text-5xl font-bold">Welcome to MyESH</h1>
                <p className="mt-2 text-lg">Your Farm. Your Market. Your Export Supply Hub.</p>
                <button className="mt-6 py-2 px-6 bg-[#1C5D57] hover:bg-teal-600 rounded-full text-white font-semibold transition-colors">
                    See What's New
                </button>
            </div>
        </div>
    </div>
);

const MarketPrices = () => {
    const prices = [
        { commodity: "Fresh Avocado (Grade 1)", price: "KES 92", trend: "up", change: "+3.2%" },
        { commodity: "Mango (Kent, Grade A)", price: "KES 55", trend: "down", change: "-3.5%" },
        { commodity: "Mango (Ngowe, Grade B)", price: "KES 32", trend: "stable", change: "0%" },
    ];

    return (
        <div>
            <h2 className="text-2xl font-bold text-[#0B3C49] dark:text-white mb-4">Market Prices</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {prices.map((p, idx) => (
                    <div
                        key={idx}
                        className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-md border border-gray-200 dark:border-gray-700"
                    >
                        <h3 className="font-semibold text-gray-700 dark:text-white">{p.commodity}</h3>
                        <div className="text-right">
                            <p className="font-bold text-lg text-gray-900 dark:text-white">{p.price}</p>
                            <div
                                className={`flex items-center justify-end text-sm font-semibold ${
                                    p.trend === 'up'
                                        ? 'text-green-500'
                                        : p.trend === 'down'
                                        ? 'text-red-500'
                                        : 'text-gray-500'
                                }`}
                            >
                                {p.change}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default DashboardPage;
